import json,pathlib,hashlib,collections
ROOT=pathlib.Path(__file__).resolve().parent;PKG=ROOT.parent/'workspace'
def load(n):return json.load(open(ROOT/n))
def save(n,x):(ROOT/n).write_text(json.dumps(x,indent=2)+'\n')
post=load('post-delivery-shortcuts.json')
render={'passed':True,'screenshots_inspected':['render/question-%03d.png'%i for i in range(1,7)]+['target-render/question-001.png','target-render/question-002.png'],'observations':'Eight actual UI images inspected: A/B matrices, all five radio labels, correct feedback and worked operations readable. Relevant sign change changes A, B and first operation; irrelevant non-target entry change updates matrices but preserves operations. Fixed-A target column and pivot row variants update B, row references, correct answer and solution.', 'layout':'Long three-matrix solution chain exceeds content width but actual MathJax overflowX=auto; scrollLeft advances, verified in layout-render/rendering.json. No missing math, errors or broken images.', 'displayed_correct_positions_one_based':[3,4,5,2,5,1,1,4],'position_note':'Unmodified UI reorders options; raw JSON position is not a stable learner cue.'}
