probes=[]
def add(cue,subgroup,scope,strategy,correct,total,baseline,conclusion,refs,disp='not_predictive'):
 probes.append(dict(cue=cue,subgroup=subgroup,scope=scope,strategy=strategy,correct=correct,total=total,baseline=baseline,disposition=disp,conclusion=conclusion,sample_refs=refs))
for dataset in ['batch','fresh-batches']:
 groups=post[dataset]['after']['groups']
 for shape,z in groups.items():
  for coord in (0,1):
   for polarity,key in [('same','same_sign'),('opposite','opposite_sign')]:
    add('Unique magnitude outlier sign',dataset+'/'+shape,'overall' if shape=='all' else 'other_recognizable_subgroup',f'Use {polarity} outlier sign and modal magnitude for operation {coord+1}; calculate only the other operation.',z[key][coord],z['total'],0.5,'Baseline 1/2 is guessing one unresolved sign after calculating the other operation. Both successes and failures occur within this visible bank shape; no deterministic bypass remains.', ['post-delivery-shortcuts.json',f'delivery-{dataset}/accepted.json','grader-report.json'])
  add('Sign of the other operation',dataset+'/'+shape,'within_template' if shape=='all' else 'other_recognizable_subgroup','Calculate second coefficient; assign first coefficient the same sign and modal magnitude.',z['same_as_other'],z['total'],0.5,'Baseline 1/2 for the uncomputed sign. All four signed answers are represented; both same-sign and opposite-sign relationships survive delivery.',['post-delivery-shortcuts.json',f'delivery-{dataset}/accepted.json'])
  add('Most frequent first coefficient',dataset+'/'+shape,'within_template' if shape=='all' else 'other_recognizable_subgroup','Take first-coordinate mode, breaking ties by displayed bank order; calculate second coefficient.',z['first_mode'],z['total'],0.5,'Baseline 1/2 for an uncomputed sign. The original invariant modal-correct relationship is absent; ties and both outcomes occur. UI further reorders tied options.',['post-delivery-shortcuts.json',f'delivery-{dataset}/accepted.json'])
add('Visible option position','eight rendered examples','overall','Always choose displayed first option.',render['displayed_correct_positions_one_based'].count(1),8,0.2,'Baseline 1/5 for five radio choices. Correct choices appear in positions 1 through 5; UI shuffling means authored position is not a stable cue.',['render-inspection.json','render-records.json','target-render-records.json'])
add('Identical bank wording, signs, order, and profile','four controlled sign cases for each of ten source profiles','within_template','Use a fixed bank-only guess for the correct pair.',10,40,0.25,'Even knowing the four plausible magnitudes gives a 1/4 baseline. Each unchanged bank supports all four correct sign pairs when matrix evidence changes; bank-only inference cannot recover either sign.',['fixed-bank-records.json','math-results.json','grader-report.json'])
